// contracts/GLDToken.sol
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "./Token.sol";
import "./Pools.sol";

contract Factory {

    // token objects
    Token public gerdaCoin;
    Token public krendelCoin;
    Token public rtkCoin;
    Token public professionalCoin;

    // poll objects
    Pool public poolGerKre;  
    Pool public poolKreRtk;


    struct user {
        string name;
    }

    mapping (address => user) public users;

    uint decimals = 12;


    constructor() {
        gerdaCoin = new Token("GerdaCoin", "GERDA", 100_000, 1);
        krendelCoin = new Token("KrendelCoin", "KRENDEL", 150_000, 2);
        rtkCoin = new Token("RTKCoin", "RTK", 300_000, 3);
        professionalCoin = new Token("Professional", "PROFI", 0, 6);

        // создание пользователей
        users[0x5B38Da6a701c568545dCfcB03FcB875f56beddC4] = user("Tom");
        users[0xAb8483F64d9C6d1EcF9b849Ae677dD3315835cb2] = user("Ben");
        users[0x78731D3Ca6b7E34aC0F824c42a7cC18A495cabaB] = user("Rick");

        gerdaCoin.transfer(address(0x5B38Da6a701c568545dCfcB03FcB875f56beddC4), 10000 * 10 ** 12);

        // создание пулов
        poolGerKre = new Pool(
            "poolGerKre",
            0x5B38Da6a701c568545dCfcB03FcB875f56beddC4,
            gerdaCoin,
            krendelCoin,
            professionalCoin
        ); // владелец том
        poolKreRtk = new Pool(
            "poolKreRtk",
            0xAb8483F64d9C6d1EcF9b849Ae677dD3315835cb2,
            krendelCoin,
            rtkCoin,
            professionalCoin
        ); // владелец бен

        // перевод токенов в пулы
        gerdaCoin.transfer(address(poolGerKre), 50000 * 10 ** 12);
        krendelCoin.transfer(address(poolGerKre), 50000 * 10 ** 12);
        rtkCoin.transfer(address(poolKreRtk), 50000 *10 ** 12);
        krendelCoin.transfer(address(poolKreRtk), 50000 * 10 ** 12);
    }

}

contracts/Token.sol.content:
// contracts/GLDToken.sol
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

contract Token is ERC20 {

    uint8 constant _decimals = 12;
    uint price;
    uint initialSupply;

    constructor(string memory _name, string memory _symbol, uint _initialSupply, uint _price) ERC20(_name, _symbol) {
        _mint(msg.sender, _initialSupply * 10 ** _decimals);
        price = _price;
        initialSupply = _initialSupply;
    }

    function getPrice() public view returns (uint) {
        return price;
    }

    function mint(address to, uint amount) public {
        _mint(to, amount);
    }

    // function buyToken()
    function buyToken(uint _amount, address _token) public payable {
        // посчитать количество того, сколько пользователь должен заплатить за токен
        uint price = _amount * Token(_token).getPrice();

        // проверить, есть ли такое количество токенов у пользователя
        require(msg.value >= price, unicode"У вас не достаточно ETH для покупки данного количества токенов");

        Token(_token).transferFrom(msg.sender, address(this), price); // перевод на контракт
        Token(_token).transfer(msg.sender, _amount); // перевод пользователю
    }

}

